/* Palette: background #f4f1de, card #ffffff, primary #3d405b, accent #e07a5f, text #2b2d42 */
* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  background-color: #f4f1de;
  color: #2b2d42;
  line-height: 1.5;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 1rem;
}

.card {
  background-color: #ffffff;
  border-radius: 12px;
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.08);
  padding: 2rem;
  width: 100%;
  max-width: 720px;
}

h1 {
  font-size: 1.75rem;
  margin-bottom: 1.5rem;
  color: #3d405b;
}

h2 {
  font-size: 1.25rem;
  margin: 1.5rem 0 0.75rem;
  color: #3d405b;
}

fieldset {
  border: none;
  margin-bottom: 1rem;
}

legend {
  font-weight: 600;
  margin-bottom: 0.5rem;
  color: #3d405b;
}

.form-row {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 0.5rem;
  margin-bottom: 0.75rem;
}

.form-row label {
  flex: 0 0 120px;
  font-weight: 500;
}

.form-row input {
  flex: 1 1 160px;
  padding: 0.5rem 0.75rem;
  border: 2px solid #d1d1d1;
  border-radius: 6px;
  font-size: 1rem;
  font-family: inherit;
  transition: border-color 0.2s;
}

.form-row input:focus {
  outline: none;
  border-color: #3d405b;
  box-shadow: 0 0 0 3px rgba(61, 64, 91, 0.2);
}

.btn-primary {
  background-color: #3d405b;
  color: #ffffff;
  border: none;
  border-radius: 6px;
  padding: 0.6rem 1.2rem;
  font-size: 1rem;
  font-weight: 600;
  cursor: pointer;
  transition: background-color 0.2s, transform 0.1s;
}

.btn-primary:hover {
  background-color: #2b2d42;
}

.btn-primary:active {
  transform: scale(0.98);
}

.btn-primary:focus-visible {
  outline: 3px solid #e07a5f;
  outline-offset: 2px;
}

table {
  width: 100%;
  border-collapse: collapse;
  margin-bottom: 0.5rem;
}

th, td {
  text-align: left;
  padding: 0.5rem 0.25rem;
  border-bottom: 1px solid #e0e0e0;
}

th {
  font-weight: 600;
  color: #3d405b;
  font-size: 0.9rem;
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

td {
  font-size: 1rem;
}

.remove-btn {
  background: none;
  border: 2px solid #e07a5f;
  color: #e07a5f;
  border-radius: 4px;
  padding: 0.25rem 0.5rem;
  font-size: 0.875rem;
  cursor: pointer;
  transition: background-color 0.2s, color 0.2s;
}

.remove-btn:hover {
  background-color: #e07a5f;
  color: #ffffff;
}

.remove-btn:active {
  transform: scale(0.95);
}

.remove-btn:focus-visible {
  outline: 3px solid #3d405b;
  outline-offset: 2px;
}

#empty-message {
  color: #6c757d;
  font-style: italic;
  padding: 0.5rem 0;
}

.totals dl {
  display: grid;
  grid-template-columns: 1fr auto;
  gap: 0.5rem 1rem;
  margin-top: 1rem;
}

.totals dt {
  font-weight: 500;
}

.totals dd {
  text-align: right;
  font-weight: 600;
}

#grand-total {
  font-size: 1.25rem;
  color: #3d405b;
}

.visually-hidden {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

[hidden] {
  display: none !important;
}

@media (max-width: 400px) {
  .card {
    padding: 1rem;
  }
  .form-row label {
    flex: 1 1 100%;
  }
  .form-row input {
    flex: 1 1 100%;
  }
  th, td {
    font-size: 0.9rem;
  }
}

let items = [];

const form = document.getElementById('invoice-form');
const descriptionInput = document.getElementById('description');
const quantityInput = document.getElementById('quantity');
const unitPriceInput = document.getElementById('unit-price');
const taxRateInput = document.getElementById('tax-rate');
const itemsBody = document.getElementById('items-body');
const emptyMessage = document.getElementById('empty-message');
const subtotalEl = document.getElementById('subtotal');
const taxEl = document.getElementById('tax');
const grandTotalEl = document.getElementById('grand-total');

function formatCurrency(value) {
  return '$' + value.toFixed(2);
}

function updateTotals() {
  const subtotal = items.reduce((sum, item) => sum + item.total, 0);
  const taxRate = parseFloat(taxRateInput.value) || 0;
  const tax = subtotal * (taxRate / 100);
  const grandTotal = subtotal + tax;

  subtotalEl.textContent = formatCurrency(subtotal);
  taxEl.textContent = formatCurrency(tax);
  grandTotalEl.textContent = formatCurrency(grandTotal);
}

function renderItems() {
  itemsBody.innerHTML = '';
  if (items.length === 0) {
    emptyMessage.hidden = false;
  } else {
    emptyMessage.hidden = true;
    items.forEach((item, index) => {
      const tr = document.createElement('tr');
      tr.innerHTML = `
        <td>${escapeHtml(item.description)}</td>
        <td>${item.quantity}</td>
        <td>${formatCurrency(item.unitPrice)}</td>
        <td>${formatCurrency(item.total)}</td>
        <td><button class="remove-btn" data-index="${index}" aria-label="Remove ${escapeHtml(item.description)}">Remove</button></td>
      `;
      itemsBody.appendChild(tr);
    });
  }
  updateTotals();
}

function escapeHtml(text) {
  const div = document.createElement('div');
  div.textContent = text;
  return div.innerHTML;
}

form.addEventListener('submit', (e) => {
  e.preventDefault();
  const description = descriptionInput.value.trim();
  const quantity = parseFloat(quantityInput.value);
  const unitPrice = parseFloat(unitPriceInput.value);

  if (!description) {
    alert('Please enter a description.');
    return;
  }
  if (isNaN(quantity) || quantity <= 0) {
    alert('Quantity must be a positive number.');
    return;
  }
  if (isNaN(unitPrice) || unitPrice <= 0) {
    alert('Unit price must be a positive number.');
    return;
  }

  items.push({
    description,
    quantity,
    unitPrice,
    total: quantity * unitPrice
  });

  renderItems();
  form.reset();
  quantityInput.value = '1';
  unitPriceInput.value = '0.00';
  descriptionInput.focus();
});

itemsBody.addEventListener('click', (e) => {
  if (e.target.classList.contains('remove-btn')) {
    const index = parseInt(e.target.dataset.index, 10);
    items.splice(index, 1);
    renderItems();
  }
});

taxRateInput.addEventListener('input', updateTotals);

// Initial render
renderItems();
